'use strict';
(()=>{
 const {$,el}=UI,key='yj-logs-v1',pref='yj-logs-save-v1',fields=['format','query','level','http','from','to'];
 const maxFile=20*1024*1024,maxTotal=40*1024*1024,maxFiles=5,maxLines=200000,encoder=new TextEncoder();
 let correlation={shifts:{},request:'',order:true};
 let files=[],records=[],filtered=[],page=1,token=0,raw=null,stale=false,remember=false,dirty=false,busy=false;
 const status=s=>$('#status').textContent=s,bytes=s=>encoder.encode(s).length,lineCount=s=>s?s.split('\n').length:0;
 function snapshot(){return{app:'yj-logs',version:2,correlation,source:$('#source').value,files:files.map(f=>({name:f.name,source:f.source})),...Object.fromEntries(fields.map(k=>[k,$('#'+k).value])),mask:$('#mask').checked}}
 function validate(v){
  if(!v||v.app!=='yj-logs'||![1,2].includes(v.version)||typeof v.source!=='string'||!['auto','text','json','access'].includes(v.format)||typeof v.query!=='string'||v.query.length>1000||!['all','FATAL','ERROR','WARN','INFO','DEBUG','UNKNOWN'].includes(v.level)||!['all','2','3','4','5'].includes(v.http)||typeof v.mask!=='boolean'||['from','to'].some(k=>typeof v[k]!=='string'||v[k]&&!/^\d{4}-\d\d-\d\dT\d\d:\d\d$/.test(v[k])))throw Error('日志备份格式不正确');
  const list=v.version===1?[]:v.files;if(!Array.isArray(list)||list.length>maxFiles)throw Error('备份文件数超过上限');
  let total=0,lines=0;const checked=[];
  for(const item of [{name:'手动输入',source:v.source},...list]){
   if(typeof item.name!=='string'||!item.name||item.name.length>180||/[\x00-\x1f\\/]/.test(item.name)||typeof item.source!=='string')throw Error('备份中有无效日志');
   const size=bytes(item.source);if(size>maxFile)throw Error('单个日志超过 20 MB');
   total+=size;lines+=lineCount(item.source);checked.push({name:item.name,source:item.source,size,lines:lineCount(item.source)});
  }
  if(list.length+Number(!!v.source)>maxFiles||total>maxTotal||lines>maxLines)throw Error('日志备份超出 5 个文件 / 40 MB / 20 万行上限');
  const c=v.correlation||{shifts:{},request:'',order:true};if(!c||typeof c.request!=='string'||c.request.length>160||typeof c.order!=='boolean'||!c.shifts||Array.isArray(c.shifts)||typeof c.shifts!=='object'||Object.keys(c.shifts).length>8||Object.entries(c.shifts).some(([k,n])=>k.length>190||!Number.isFinite(n)||Math.abs(n)>1440))throw Error('时间关联设置无效');return{...v,version:2,correlation:c,files:checked.slice(1)};
 }
 function persist(){if(!remember)return;try{if(stale||localStorage.getItem(key)!==raw){stale=true;throw Error('另一标签页已修改内容，请先备份当前工作区并重新打开页面')}const serialized=JSON.stringify(snapshot());localStorage.setItem(key,serialized);raw=serialized;$('#storage-note').textContent='当前日志已保存到此浏览器；建议另存完整备份。'}catch(e){$('#storage-note').textContent='未能保存当前全部日志：'+e.message+'。大文件可能超过浏览器容量，请下载完整备份；重新打开页面可能看到上次保存的内容。'}}
 function apply(v){correlation=v.correlation||{shifts:{},request:'',order:true};$('#source').value=v.source;files=v.files.map(f=>({...f}));fields.forEach(k=>$('#'+k).value=v[k]);$('#mask').checked=v.mask;dirty=true;renderFiles()}
 const scrub=s=>s.replace(/\b(?:\d{1,3}\.){3}\d{1,3}\b/g,'[IP]').replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi,'[EMAIL]').replace(/\b(Bearer\s+)[A-Za-z0-9._~+\/-]+=*/gi,'$1[REDACTED]').replace(/(["']?\b(?:password|passwd|token|secret|api[_-]?key|authorization|cookie)["']?\s*[:=]\s*)(?:"[^"\r\n]*"|'[^'\r\n]*'|[^\s,;]+)/gi,'$1[REDACTED]');
 function parsed(line,n,source){let text=line,time='',level='UNKNOWN',http='';const fmt=$('#format').value;let j;if(fmt==='json'||fmt==='auto'&&line.trimStart().startsWith('{'))try{j=JSON.parse(line);if(j&&typeof j==='object'&&!Array.isArray(j)){time=String(j.timestamp??j.time??j['@timestamp']??'');level=String(j.level??j.severity??'').toUpperCase();http=String(j.status??j.statusCode??'')}}catch{}if(!j&&(fmt==='access'||fmt==='auto')){const m=line.match(/^\S+\s+\S+\s+\S+\s+\[([^\]]+)\]\s+"[^"\r\n]*"\s+(\d{3})\b/);if(m){time=m[1].replace(/^(\d\d)\/(\w{3})\/(\d{4}):(\d\d:\d\d:\d\d) ([+-]\d{4})$/,'$1 $2 $3 $4 $5');http=m[2]}}
  if(!time){const m=line.match(/\b\d{4}-\d\d-\d\d[T ]\d\d:\d\d:\d\d(?:\.\d+)?(?:Z|[+-]\d\d:?\d\d)?/);if(m)time=m[0]}if(!['FATAL','ERROR','WARN','INFO','DEBUG'].includes(level)){const m=line.match(/\b(FATAL|CRITICAL|ERROR|WARN(?:ING)?|INFO|DEBUG|TRACE)\b/i);level=m?m[1].toUpperCase():'UNKNOWN';if(level==='WARNING')level='WARN';if(level==='CRITICAL')level='FATAL';if(level==='TRACE')level='DEBUG'}if(/^\d{3}$/.test(http)&&Number(http)>=400&&level==='UNKNOWN')level=Number(http)>=500?'ERROR':'WARN';if(!/^\d{3}$/.test(http))http='';const at=Date.parse(time);return{n,source,text,time,at:Number.isFinite(at)?at:null,level,http}}
 function sources(){const list=[];if($('#source').value)list.push({name:'手动输入',source:$('#source').value});return list.concat(files)}
 function limits(list){if(list.length>maxFiles)throw Error('最多选择 5 份日志（包含手动输入）');let total=0,lines=0;for(const f of list){const size=f.size??bytes(f.source),count=f.lines??lineCount(f.source);if(size>maxFile)throw Error(f.name+' 超过单文件 20 MB 上限');total+=size;lines+=count}if(total>maxTotal)throw Error('日志合计超过 40 MB');if(lines>maxLines)throw Error('日志合计超过 20 万行');return{total,lines}}
 function renderFiles(){const host=$('#file-list');host.replaceChildren();if(!files.length){host.append(el('p',{class:'hint'},'尚未添加文件；也可以只粘贴日志。'));return}files.forEach((f,i)=>{const row=el('div',{class:'log-file-row'}),label=el('span',{},(i+1)+'. '+f.name+' · '+(f.size/1048576).toFixed(2)+' MB · '+f.lines+' 行'),remove=el('button',{type:'button','aria-label':'移除 '+f.name},'移除');remove.disabled=busy;remove.onclick=()=>{files.splice(i,1);dirty=true;renderFiles();render();persist();status('已移除文件，重新分析后结果会更新。')};row.append(label,remove);host.append(row)})}
 function controls(){for(const id of ['log-file','analyze','sample','clear','format','source'])$('#'+id).disabled=busy;$('#cancel-analysis').hidden=!busy;renderFiles()}
 function render(){window.dispatchEvent(new Event('yj-logs-update'));const q=$('#query').value.toLowerCase(),lv=$('#level').value,h=$('#http').value,a=$('#from').value?Date.parse($('#from').value):-Infinity,b=$('#to').value?Date.parse($('#to').value):Infinity;filtered=records.filter(r=>(!q||r.text.toLowerCase().includes(q)||r.source.toLowerCase().includes(q))&&(lv==='all'||r.level===lv)&&(h==='all'||r.http.startsWith(h))&&((a===-Infinity&&b===Infinity)||(r.at!==null&&r.at>=a&&r.at<=b)));const pages=Math.max(1,Math.ceil(filtered.length/50));page=Math.max(1,Math.min(page,pages));$('#rows').replaceChildren(...filtered.slice((page-1)*50,page*50).map(r=>{const tr=el('tr');tr.append(el('td',{},r.source),el('td',{},r.n),el('td',{},r.time||'—'));const level=el('td');level.append(el('span',{class:'log-level '+r.level},r.level));tr.append(level,el('td',{},r.http||'—'));const td=el('td');td.append(el('pre',{},$('#mask').checked?scrub(r.text):r.text));tr.append(td);return tr}));$('#page').textContent=page+' / '+pages+' 页';$('#prev').disabled=page===1;$('#next').disabled=page===pages;$('#summary').textContent='匹配 '+filtered.length+' / '+records.length+' 行 · '+sources().length+' 份来源'+(dirty?' · 输入已变化，请重新分析':'');$('#metrics').replaceChildren(...[['有效日志行',records.length],['错误 / 严重',records.filter(r=>['ERROR','FATAL'].includes(r.level)).length],['警告',records.filter(r=>r.level==='WARN').length],['HTTP 5xx',records.filter(r=>r.http.startsWith('5')).length]].map(([name,count])=>{const n=el('div',{class:'local-metric'});n.append(el('span',{class:'hint'},name),el('strong',{},count));return n}))}
 async function analyze(){if(busy)return;const generation=++token,list=sources();let check;try{check=limits(list)}catch(e){status(e.message);return}busy=true;controls();$('#progress').hidden=false;$('#progress').max=Math.max(check.lines,1);$('#progress').value=0;records=[];filtered=[];page=1;render();status('正在本机逐批分析…');let done=0;
  try{for(const item of list){const lines=item.source.split('\n');for(let i=0;i<lines.length;i+=500){if(generation!==token)return;for(let j=i;j<Math.min(i+500,lines.length);j++)if(lines[j].trim())records.push(parsed(lines[j].replace(/\r$/,''),j+1,item.name));done+=Math.min(500,lines.length-i);$('#progress').value=done;status('正在分析 '+item.name+' · '+done+' / '+check.lines+' 行');await new Promise(requestAnimationFrame)}}if(generation!==token)return;dirty=false;render();persist();status('分析完成：'+records.length+' 条有效日志，来自 '+list.length+' 份来源；没有上传。')}catch(e){records=[];render();status('分析未完成：'+e.message)}finally{if(generation===token){busy=false;controls();$('#progress').hidden=true}}}
 $('#cancel-analysis').onclick=()=>{if(!busy)return;++token;busy=false;records=[];filtered=[];dirty=true;controls();$('#progress').hidden=true;render();status('已取消，已导入的文件仍保留，可重新分析。')};
 $('#analyze').onclick=analyze;$('#source').oninput=()=>{dirty=true;render();persist()};$('#format').onchange=()=>{dirty=true;render();persist()};for(const k of fields.slice(1))$('#'+k).oninput=()=>{page=1;render();persist()};$('#mask').onchange=()=>{render();persist()};$('#prev').onclick=()=>{page--;render()};$('#next').onclick=()=>{page++;render()};
 $('#log-file').onchange=async e=>{const selected=[...e.target.files];e.target.value='';if(!selected.length||busy)return;const before=++token;busy=true;controls();const pending=[];
  try{if(files.length+selected.length+Number(!!$('#source').value)>maxFiles)throw Error('最多 5 份日志，包含手动输入');if(selected.some(f=>f.size>maxFile))throw Error('单文件不能超过 20 MB');if(selected.reduce((n,f)=>n+f.size,files.reduce((n,f)=>n+f.size,bytes($('#source').value)))>maxTotal)throw Error('日志合计不能超过 40 MB');for(const f of selected){status('正在本机读取 '+f.name+'…');const source=await f.text();if(token!==before)return;const item={name:f.name.slice(0,180).replace(/[\x00-\x1f\\/]/g,'_')||'未命名日志',source,size:bytes(source),lines:lineCount(source)};pending.push(item);limits(sources().concat(pending));await new Promise(requestAnimationFrame)}if(token!==before)return;for(const item of pending){const base=item.name;let n=2;while(files.some(f=>f.name===item.name)||pending.some(p=>p!==item&&p.name===item.name))item.name=base+' ('+(n++)+')';files.push(item)}dirty=true;busy=false;controls();render();await analyze()}catch(err){if(token===before){busy=false;controls();status('本批文件未添加：'+err.message)}}};
 $('#sample').onclick=()=>{if(sources().length&&!confirm('用公开示例替换当前全部日志？建议先备份。'))return;files=[];$('#source').value='2026-01-01T09:00:00Z INFO example service started\n2026-01-01T09:00:01Z WARN retry for 192.0.2.10\n'+JSON.stringify({timestamp:'2026-01-01T09:00:02Z',level:'ERROR',message:'公开测试错误',token:'example-token'})+'\n192.0.2.20 - - [01/Jan/2026:09:00:03 +0000] "GET /example HTTP/1.1" 503 42';renderFiles();analyze()};
 function result(type){if(dirty){status('日志或解析方式已变化，请先重新分析再导出。');return}if(!$('#mask').checked&&!confirm('将导出未经脱敏的日志，确认继续？'))return;const cell=s=>{s=String(s);if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'},text=r=>$('#mask').checked?scrub(r.text):r.text;if(type==='txt')UI.download('筛选日志.txt',filtered.map(r=>'['+r.source+':'+r.n+'] '+text(r)).join('\n'),'text/plain;charset=utf-8');else UI.download('筛选日志.csv','\ufeff'+[['来源文件','行号','时间','级别','HTTP','内容'],...filtered.map(r=>[r.source,r.n,r.time,r.level,r.http,text(r)])].map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
 $('#export-txt').onclick=()=>result('txt');$('#export-csv').onclick=()=>result('csv');
 $('#remember').onchange=()=>{if($('#remember').checked&&!confirm('原始日志可能含隐私。开启后将保存在此浏览器，但大日志可能超过浏览器容量。继续？')){$('#remember').checked=false;return}remember=$('#remember').checked;try{localStorage.setItem(pref,String(remember));if(!remember){localStorage.removeItem(key);raw=null;$('#storage-note').textContent='已关闭本机保存；当前内容只在内存。'}}catch{}persist();status(remember?'已尝试开启本机保存；请确认下方保存状态并定期下载完整备份。':'已移除本工具保存记录，当前日志仅在内存。')};
 $('#clear').onclick=()=>{if(!confirm('清空本工具日志及保存数据？需要留存请先备份。'))return;++token;busy=false;files=[];correlation={shifts:{},request:'',order:true};$('#source').value='';records=[];raw=null;stale=false;dirty=false;try{localStorage.removeItem(key)}catch{}controls();$('#progress').hidden=true;render();$('#storage-note').textContent='';status('本工具日志已清空，其他工具不受影响。')};
 try{remember=localStorage.getItem(pref)==='true';raw=localStorage.getItem(key);if(remember&&raw)apply(validate(JSON.parse(raw)))}catch{stale=true;status('旧日志记录无法读取，未覆盖；请恢复有效备份。')}$('#remember').checked=remember;controls();render();if(sources().length)analyze();window.addEventListener('storage',e=>{if(e.key===key){stale=true;status('另一标签页已修改日志，先备份当前内容再重新打开页面。')}});
 ToolBackup.register({id:'logs',name:'本地日志分析台',maxBackupBytes:64*1024*1024,get:snapshot,validate,restore:async v=>{++token;busy=false;apply(v);stale=false;raw=localStorage.getItem(key);controls();await analyze()}});
 window.LocalLogs={correlation:()=>JSON.parse(JSON.stringify(correlation)),setCorrelation:value=>{correlation=JSON.parse(JSON.stringify(value));validate(snapshot());persist()},scrub,parse:parsed,state:snapshot,validate,records:()=>dirty?[]:records.map((r,index)=>({...r,index})),masked:()=>$('#mask').checked,busy:()=>busy};
})();
